div.script:
document.addEventListener('DOMContentLoaded', function() {
    const btnApply = document.getElementById('btn_apply_coupon');
    const couponInput = document.getElementById('coupon_code');
    const couponMsg = document.getElementById('coupon_msg');

    const discountRow = document.getElementById('summary_discount_row');
    const discountVal = document.getElementById('summary_discount_val');
    const totalVal = document.getElementById('summary_total_val');

    if (btnApply && couponInput) {
        btnApply.addEventListener('click', function() {
            const couponCode = couponInput.value.trim();
            if (!couponCode) {
                couponMsg.style.display = 'none';
                if (discountRow) discountRow.setAttribute('style', 'display: none !important;');
                return;
            }

            const planId = "";

            btnApply.innerHTML = ' Applying...';
            btnApply.disabled = true;

            fetch('/subscriptions/checkout/validate_coupon', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        coupon_code: couponCode,
                        plan_id: planId
                    }
                })
            })
            .then(res => res.json())
            .then(data => {
                btnApply.innerHTML = 'Apply';
                btnApply.disabled = false;

                const result = data.result;
                if (result && result.valid) {
                    couponMsg.className = 'mt-2 small text-success';
                    couponMsg.innerHTML = ' ' + result.message;
                    couponMsg.style.display = 'block';

                    if (discountRow && discountVal && totalVal) {
                        discountVal.innerHTML = '-' + result.discount_amount;
                        discountRow.style.display = 'flex';
                        discountRow.removeAttribute('style'); // Remove the !important display: none

                        // Update total
                        totalVal.innerHTML = result.new_total;
                    }
                } else {
                    couponMsg.className = 'mt-2 small text-danger';
                    couponMsg.innerHTML = ' ' + (result ? result.message : 'Invalid coupon code.');
                    couponMsg.style.display = 'block';

                    if (discountRow) discountRow.setAttribute('style', 'display: none !important;');
                }
            })
            .catch(err => {
                btnApply.innerHTML = 'Apply';
                btnApply.disabled = false;
                console.error('Error applying coupon:', err);
            });
        });
    }

    // We removed custom provider toggles because we are using Odoo's native payment system
});
